customCSS:
.t, .history { color: #848cb5; }
.join { color: #587539; }
.part, .quit { color: #848cb5; }
.kick, .error { color: #f52a65; }
.notice { color: #8c6c3e; }
.action { color: #9854f1; }
.mode, .nick, .topic, .server { color: #007197; }
.highlight { color: #3760bf; background-color: #b7c1e3; border-left: 3px solid #9854f1; padding-left: 8px; }
.reply { color: #848cb5; border-left: 2px solid #2e7de9; padding-left: 6px; }
.oper { color: #e1e2e7; background-color: #8c6c3e; }
.reactions { color: #2e7de9; background-color: #d0d5e3; }
.card { background-color: #d0d5e3; border-color: #848cb5; }
.card-title { color: #2e7de9; }
.card-desc { color: #848cb5; }
.daychange { color: #848cb5; border-color: #d0d5e3; }
